/* AMCA CMAC starter question bank - 300 questions.
   Independent study questions aligned to the AMCA Clinical Medical Assistant
   content domains, distributed by the exam category weights. Loaded into
   Firestore via the admin "Seed" button (which REPLACES the starter bank).
   Each: { cat, q, choices[], answer (0-based index), why }
   Counts: infection 30, ecg 15, specimens 75, physexam 24, meds 21, intake 15,
   reception 18, records 18, coordination 9, billing 21, management 12,
   professionalism 30, lawethics 12  (= 300). */
const SEED_QUESTIONS = [

/* ========== Infection Control (30) ========== */
{cat:"infection", q:"What is the single most effective way to prevent the spread of infection?", choices:["Wearing gloves at all times","Hand hygiene","Taking antibiotics","Wearing a gown"], answer:1, why:"Hand hygiene (handwashing or alcohol-based sanitizer) is the single most effective measure to prevent transmission of microorganisms."},
{cat:"infection", q:"Standard Precautions are based on the principle that:", choices:["Only visibly ill patients are infectious","All blood and body fluids are treated as potentially infectious","Gloves replace handwashing","Masks are only needed in surgery"], answer:1, why:"Standard Precautions treat all blood, body fluids, secretions, and excretions (except sweat) as potentially infectious, regardless of diagnosis."},
{cat:"infection", q:"When donning PPE, which item is put on LAST?", choices:["Gown","Mask","Goggles","Gloves"], answer:3, why:"PPE is applied gown then mask, then goggles/face shield, then gloves, so gloves go on last and cover the gown cuffs."},
{cat:"infection", q:"When removing PPE, which item is generally removed FIRST?", choices:["Gloves","Mask","Gown","Shoe covers"], answer:0, why:"Gloves are the most contaminated item and are removed first; the mask is removed last, after leaving the patient area."},
{cat:"infection", q:"An autoclave achieves sterilization using:", choices:["Dry heat","Pressurized steam","A chemical soak","Ultraviolet light"], answer:1, why:"An autoclave sterilizes with pressurized saturated steam (about 250 degrees F / 121 C at 15 psi), destroying all microorganisms and spores."},
{cat:"infection", q:"Medical asepsis (clean technique) is best described as:", choices:["Eliminating all microorganisms including spores","Reducing the number and spread of microorganisms","Wearing only sterile gloves","Sterilizing every surface"], answer:1, why:"Medical asepsis reduces the number and transfer of pathogens; surgical asepsis (sterile technique) eliminates all microorganisms and spores."},
{cat:"infection", q:"Surgical asepsis (sterile technique) is required for:", choices:["Taking a blood pressure","Invasive procedures such as surgery or catheter insertion","Greeting a patient","Filing charts"], answer:1, why:"Surgical asepsis keeps an area free of all microorganisms and is required for invasive procedures that enter sterile body areas."},
{cat:"infection", q:"OSHA's Bloodborne Pathogens Standard requires employers to provide:", choices:["Annual flu shots only","An exposure control plan, PPE, and the hepatitis B vaccine offer","Daily autoclaving of desks","Patient consent forms"], answer:1, why:"The standard requires an exposure control plan, PPE, the offer of hepatitis B vaccination, and proper sharps handling to protect workers."},
{cat:"infection", q:"Tuberculosis (TB) requires which type of transmission-based precautions?", choices:["Contact","Droplet","Airborne","Standard only"], answer:2, why:"TB spreads by tiny airborne droplet nuclei, requiring airborne precautions including an N95 respirator and a negative-pressure room."},
{cat:"infection", q:"Which respirator is required when caring for a patient with active tuberculosis?", choices:["Surgical mask","N95 respirator","Cloth mask","No mask needed"], answer:1, why:"A fit-tested N95 (or higher) respirator filters the small airborne particles that carry TB; a surgical mask is not sufficient."},
{cat:"infection", q:"Clostridioides difficile (C. diff) is best removed from the hands by:", choices:["Alcohol-based hand sanitizer","Washing with soap and water","Wearing gloves only","Air drying"], answer:1, why:"Alcohol sanitizer does not kill C. diff spores; soap and water with friction physically removes them."},
{cat:"infection", q:"The six links in the chain of infection include the infectious agent, reservoir, portal of exit, mode of transmission, portal of entry, and:", choices:["Susceptible host","Antibiotic","Vaccine","Gown"], answer:0, why:"The chain of infection ends with a susceptible host; breaking any single link stops the spread of infection."},
{cat:"infection", q:"A used needle should be disposed of in:", choices:["The regular trash","A puncture-proof sharps container","A red biohazard bag","A recycling bin"], answer:1, why:"Sharps go directly into a labeled, puncture-resistant sharps container to prevent needlestick injuries."},
{cat:"infection", q:"To prevent needlestick injury, used needles should:", choices:["Be recapped by hand","Never be recapped and be discarded immediately","Be bent before disposal","Be left on the tray"], answer:1, why:"Recapping by hand is a leading cause of needlesticks; needles should not be recapped and should go straight into the sharps container."},
{cat:"infection", q:"Items contaminated with blood or body fluids are discarded in a:", choices:["Clear plastic bag","Red biohazard bag","Brown paper bag","Sharps container"], answer:1, why:"Regulated medical (biohazard) waste contaminated with blood/body fluids goes in a labeled red biohazard bag."},
{cat:"infection", q:"Sanitization refers to:", choices:["Destroying all microorganisms and spores","Reducing microorganisms to a safe level and removing debris","Killing only viruses","Sterilizing instruments"], answer:1, why:"Sanitization (cleaning) removes debris and lowers microbial counts to a safe level; it is the first step before disinfection or sterilization."},
{cat:"infection", q:"Disinfection differs from sterilization in that disinfection:", choices:["Kills all microorganisms including spores","Destroys most pathogens but not necessarily all spores","Only cleans visible dirt","Is used only on skin"], answer:1, why:"Disinfection destroys most pathogens on surfaces/instruments but may not kill all bacterial spores; sterilization destroys everything including spores."},
{cat:"infection", q:"Influenza is spread primarily by:", choices:["Airborne nuclei","Respiratory droplets","Contaminated needles","Insect bites"], answer:1, why:"Influenza spreads mainly through respiratory droplets, which calls for droplet precautions (surgical mask within close range)."},
{cat:"infection", q:"A healthcare-associated infection (HAI) is one that:", choices:["The patient had on arrival","Is acquired while receiving care in a facility","Only affects staff","Cannot be prevented"], answer:1, why:"An HAI (nosocomial infection) is acquired during the course of care and was not present on admission."},
{cat:"infection", q:"Normal flora are:", choices:["Always harmful","Microorganisms normally present that usually cause no harm","Only found in hospitals","Types of vaccines"], answer:1, why:"Normal flora are resident microorganisms (e.g., in the gut and on skin) that usually cause no harm and may help protect the host."},
{cat:"infection", q:"An autoclave indicator strip or tape is used to confirm that:", choices:["The water is hot","Sterilization conditions were met","Instruments are dry","The door is closed"], answer:1, why:"Sterilization indicators change to verify the load reached the proper temperature/exposure; biological indicators (spore tests) confirm spore kill."},
{cat:"infection", q:"After a needlestick exposure, the medical assistant should FIRST:", choices:["Finish the task","Wash the area with soap and water and report it immediately","Apply a bandage and ignore it","Wait until the end of shift"], answer:1, why:"Immediately wash the site, then report the exposure per the exposure control plan so post-exposure evaluation can begin promptly."},
{cat:"infection", q:"Which organism type is a virus?", choices:["E. coli","Influenza","Candida","Giardia"], answer:1, why:"Influenza is a virus; E. coli is a bacterium, Candida is a fungus, and Giardia is a protozoan."},
{cat:"infection", q:"MRSA is typically managed with which precautions?", choices:["Airborne","Contact","Droplet","None"], answer:1, why:"MRSA spreads by direct/indirect contact, requiring contact precautions such as gloves and gown."},
{cat:"infection", q:"Hepatitis B, hepatitis C, and HIV are examples of:", choices:["Airborne diseases","Bloodborne pathogens","Foodborne illnesses","Fungal infections"], answer:1, why:"HBV, HCV, and HIV are bloodborne pathogens transmitted through blood and certain body fluids."},
{cat:"infection", q:"A vaccine is available to protect healthcare workers against:", choices:["Hepatitis C","Hepatitis B","HIV","The common cold"], answer:1, why:"A hepatitis B vaccine exists and must be offered to at-risk workers; there is no vaccine for hepatitis C or HIV."},
{cat:"infection", q:"Antibiotic resistance is promoted by:", choices:["Finishing prescribed antibiotics","Overuse and misuse of antibiotics","Hand hygiene","Vaccination"], answer:1, why:"Overusing or misusing antibiotics selects for resistant organisms; appropriate use and completing prescriptions help prevent resistance."},
{cat:"infection", q:"A Safety Data Sheet (SDS) provides information about:", choices:["Patient diagnoses","Hazards and safe handling of a chemical","Insurance billing","Appointment scheduling"], answer:1, why:"The SDS lists a chemical's hazards, handling, storage, and first-aid measures and must be readily accessible to staff."},
{cat:"infection", q:"The best way to break the chain of infection at the 'mode of transmission' link is:", choices:["Giving antibiotics","Hand hygiene and proper PPE","Isolating the building","Increasing fluids"], answer:1, why:"Hand hygiene, PPE, and disinfection interrupt how pathogens move from one host to another."},
{cat:"infection", q:"Sterile gloves become contaminated if:", choices:["They stay above the waist","They touch a non-sterile surface","They remain in the sterile field","They are kept in sight"], answer:1, why:"Touching anything outside the sterile field contaminates sterile gloves; the field must stay in sight and above waist level."},

/* ========== ECG Testing (15) ========== */
{cat:"ecg", q:"The heart's natural pacemaker is the:", choices:["AV node","SA node","Purkinje fibers","Bundle of His"], answer:1, why:"The sinoatrial (SA) node initiates the normal electrical impulse and sets the heart rate."},
{cat:"ecg", q:"On an ECG, the P wave represents:", choices:["Ventricular depolarization","Atrial depolarization","Ventricular repolarization","SA node repolarization"], answer:1, why:"The P wave reflects atrial depolarization, which causes the atria to contract."},
{cat:"ecg", q:"The QRS complex on an ECG represents:", choices:["Atrial depolarization","Ventricular depolarization","Ventricular repolarization","Atrial repolarization"], answer:1, why:"The QRS complex represents ventricular depolarization, which triggers ventricular contraction."},
{cat:"ecg", q:"The T wave on an ECG represents:", choices:["Atrial depolarization","Ventricular repolarization","Ventricular depolarization","SA node firing"], answer:1, why:"The T wave represents ventricular repolarization, the recovery phase of the ventricles."},
{cat:"ecg", q:"Standard ECG paper runs at a speed of:", choices:["10 mm/sec","25 mm/sec","50 mm/sec","100 mm/sec"], answer:1, why:"Standard ECG recording speed is 25 mm/second; each small box equals 0.04 second."},
{cat:"ecg", q:"A standard 12-lead ECG uses how many electrodes?", choices:["6","10","12","4"], answer:1, why:"Ten electrodes (6 chest/precordial plus 4 limb) produce the 12 leads (views) of the heart."},
{cat:"ecg", q:"Lead V1 is correctly placed at the:", choices:["4th intercostal space, right sternal border","5th intercostal space, midclavicular line","2nd intercostal space, left border","Left anterior axillary line"], answer:0, why:"V1 is placed at the 4th intercostal space at the right sternal border; V2 mirrors it on the left."},
{cat:"ecg", q:"Lead V2 is placed at the:", choices:["4th intercostal space, left sternal border","5th intercostal space, midaxillary line","Right sternal border, 2nd space","Midclavicular line, 6th space"], answer:0, why:"V2 sits at the 4th intercostal space at the left sternal border, directly across from V1."},
{cat:"ecg", q:"Wandering baseline or muscle artifact on an ECG is most often caused by:", choices:["Correct lead placement","Patient movement or loose electrodes","A normal heart rhythm","Good skin preparation"], answer:1, why:"Artifact usually results from patient movement, shivering, or poor electrode contact; proper skin prep and a still patient reduce it."},
{cat:"ecg", q:"To reduce ECG artifact from poor skin contact, the MA should:", choices:["Apply electrodes over hair and lotion","Clean and lightly abrade the skin and ensure good electrode contact","Increase the paper speed","Use fewer leads"], answer:1, why:"Cleaning, drying, and lightly prepping the skin (removing oils/hair) improves electrode adhesion and signal quality."},
{cat:"ecg", q:"The PR interval represents the time for the impulse to travel from the:", choices:["Ventricles to atria","Atria through the AV node to the ventricles","SA node to the lungs","Apex to the base"], answer:1, why:"The PR interval measures conduction time from atrial depolarization through the AV node to the start of ventricular depolarization."},
{cat:"ecg", q:"A normal adult heart rate on an ECG is:", choices:["Less than 40 bpm","60 to 100 bpm","100 to 150 bpm","Over 150 bpm"], answer:1, why:"A normal sinus rhythm in adults is 60 to 100 beats per minute."},
{cat:"ecg", q:"A heart rate over 100 bpm is termed:", choices:["Bradycardia","Tachycardia","Asystole","Arrhythmia"], answer:1, why:"Tachycardia is a heart rate above 100 bpm; bradycardia is below 60 bpm."},
{cat:"ecg", q:"A heart rate under 60 bpm is termed:", choices:["Tachycardia","Bradycardia","Fibrillation","Flutter"], answer:1, why:"Bradycardia is a heart rate below 60 beats per minute."},
{cat:"ecg", q:"Before an ECG, the patient should be positioned:", choices:["Standing","Supine and relaxed","Prone","Sitting upright with legs crossed"], answer:1, why:"A supine, relaxed position minimizes muscle artifact and allows accurate electrode placement."},

/* ========== Collecting Specimens & Diagnostic Testing (75) ========== */
{cat:"specimens", q:"In the order of draw, the first tube collected after blood culture bottles is:", choices:["Lavender (EDTA)","Light blue (sodium citrate)","Red (no additive)","Green (heparin)"], answer:1, why:"Order of draw: blood cultures, then light blue (citrate), serum (red/gold), green (heparin), lavender (EDTA), then gray, preventing additive carryover."},
{cat:"specimens", q:"A lavender-top (EDTA) tube is most commonly used for a:", choices:["Coagulation panel","Complete blood count (CBC)","Blood culture","Glucose tolerance test"], answer:1, why:"EDTA prevents clotting and preserves cell shape, making it ideal for hematology tests such as the CBC."},
{cat:"specimens", q:"The additive in a light-blue tube is:", choices:["EDTA","Sodium citrate","Sodium fluoride","Heparin"], answer:1, why:"Light-blue tubes contain sodium citrate for coagulation studies (PT/INR, PTT); the 9:1 blood-to-additive ratio must be exact."},
{cat:"specimens", q:"A light-blue (sodium citrate) tube is used for:", choices:["CBC","Coagulation studies (PT/INR, PTT)","Glucose","Blood typing"], answer:1, why:"Sodium citrate is the anticoagulant for coagulation testing such as PT/INR and PTT."},
{cat:"specimens", q:"A red-top tube (no additive) yields:", choices:["Whole blood","Serum after clotting","Plasma","Buffy coat"], answer:1, why:"With no anticoagulant, blood clots in a red top and is centrifuged to produce serum for chemistry and serology tests."},
{cat:"specimens", q:"A gold-top or SST (serum separator) tube contains a:", choices:["Strong anticoagulant","Gel separator and clot activator","Sodium citrate","Sodium fluoride"], answer:1, why:"The SST has a clot activator and a gel that separates serum from cells after centrifugation, used for many chemistry tests."},
{cat:"specimens", q:"The gray-top tube contains sodium fluoride, which works to:", choices:["Detect infection","Preserve glucose by inhibiting glycolysis","Run a CBC","Measure clotting time"], answer:1, why:"Sodium fluoride is an antiglycolytic agent that preserves glucose, used for glucose and lactate testing."},
{cat:"specimens", q:"A green-top tube contains:", choices:["EDTA","Heparin","Sodium citrate","No additive"], answer:1, why:"Green tubes contain heparin (an anticoagulant) and are used for many plasma chemistry tests."},
{cat:"specimens", q:"The vein most commonly used for routine venipuncture is the:", choices:["Cephalic vein","Median cubital vein","Basilic vein","Femoral vein"], answer:1, why:"The median cubital vein in the antecubital fossa is preferred because it is large, well-anchored, and away from major nerves and arteries."},
{cat:"specimens", q:"Which antecubital vein carries the highest risk of nerve or artery injury and is chosen last?", choices:["Median cubital","Cephalic","Basilic","Median"], answer:2, why:"The basilic vein lies near the brachial artery and median nerve, so it is selected only when other veins are unavailable."},
{cat:"specimens", q:"The needle angle for routine venipuncture should be:", choices:["15 to 30 degrees","45 degrees","60 degrees","90 degrees"], answer:0, why:"Insert at 15 to 30 degrees with the bevel up to enter the vein smoothly without passing through it."},
{cat:"specimens", q:"A tourniquet should NOT remain on the arm longer than:", choices:["1 minute","3 minutes","5 minutes","10 minutes"], answer:0, why:"Leaving a tourniquet on longer than 1 minute can cause hemoconcentration and alter test results."},
{cat:"specimens", q:"The tourniquet should be applied how far above the venipuncture site?", choices:["1 to 2 inches","3 to 4 inches","6 to 8 inches","Directly over the site"], answer:1, why:"A tourniquet is placed about 3 to 4 inches above the intended site to engorge the veins without obscuring the area."},
{cat:"specimens", q:"A patient becomes pale and faint during a blood draw. The medical assistant should FIRST:", choices:["Quickly finish the draw","Remove the tourniquet and needle and stop the draw","Offer the patient water","Tighten the tourniquet"], answer:1, why:"Stop the procedure immediately, remove the tourniquet and needle, then protect the patient from falling and treat the syncope."},
{cat:"specimens", q:"Hemolysis of a blood specimen can be caused by:", choices:["Gentle handling","Vigorous shaking of the tube","Filling the tube completely","Using the correct needle size"], answer:1, why:"Rough handling, vigorous shaking, or a too-small needle ruptures red cells (hemolysis), which can invalidate results."},
{cat:"specimens", q:"To avoid hemolysis, anticoagulant tubes should be mixed by:", choices:["Shaking hard 20 times","Gently inverting several times","Centrifuging immediately","Leaving them still"], answer:1, why:"Gentle inversion mixes the additive without damaging cells; shaking causes hemolysis."},
{cat:"specimens", q:"A hematoma during venipuncture is caused by:", choices:["Blood leaking into surrounding tissue","Too little blood drawn","A clean stick","Proper technique"], answer:0, why:"A hematoma forms when blood leaks into the tissue, often from the needle going through the vein or inadequate pressure afterward."},
{cat:"specimens", q:"After removing the needle, the MA should:", choices:["Massage the site vigorously","Apply firm pressure with gauze","Leave the site open","Recap the needle by hand"], answer:1, why:"Firm pressure with gauze (and elevation) stops bleeding and helps prevent a hematoma; the site should not be massaged."},
{cat:"specimens", q:"A blood or other specimen should be labeled:", choices:["The next day","At the patient's side, immediately after collection","Only if the result is abnormal","Later, in the lab"], answer:1, why:"Specimens are labeled at the point of collection in the patient's presence to prevent identification and mix-up errors."},
{cat:"specimens", q:"A specimen label must include the patient's name and at least one other identifier, such as:", choices:["The MA's lunch break","Date of birth","Room temperature","The needle gauge"], answer:1, why:"At least two identifiers (e.g., name and date of birth), plus date/time and collector initials, are required to avoid misidentification."},
{cat:"specimens", q:"For a capillary (dermal) puncture, the recommended site in an adult is the:", choices:["Earlobe","Side of the fingertip (3rd or 4th finger)","Center of the fingertip","Thumb"], answer:1, why:"The side of the fleshy tip of the 3rd or 4th finger is used; the center and very tip are avoided due to nerves and thinner tissue."},
{cat:"specimens", q:"A heel stick for capillary blood is used primarily on:", choices:["Adults","Infants under 1 year","Teenagers","The elderly"], answer:1, why:"The heel is the preferred capillary site for infants because their fingers are too small for safe puncture."},
{cat:"specimens", q:"In capillary collection, the first drop of blood should be:", choices:["Collected for testing","Wiped away","Saved for the lab","Smeared on a slide"], answer:1, why:"The first drop contains tissue fluid and is wiped away to avoid diluting and contaminating the specimen."},
{cat:"specimens", q:"The order of draw for capillary (microcollection) tubes places which test first?", choices:["Serum tubes","EDTA (lavender) tubes","Clot tubes","Gel tubes"], answer:1, why:"For capillary collection, EDTA tubes are filled first to ensure adequate volume before platelets begin to clump."},
{cat:"specimens", q:"A clean-catch midstream urine specimen is collected primarily to:", choices:["Increase the volume","Reduce contamination from skin and genital flora","Speed up testing","Test only for glucose"], answer:1, why:"Cleansing the area and catching the midstream reduces contamination, giving a more accurate culture and urinalysis."},
{cat:"specimens", q:"A 24-hour urine specimen requires the patient to:", choices:["Collect only the first morning sample","Discard the first void, then collect all urine for 24 hours","Collect one random sample","Refrigerate nothing"], answer:1, why:"The first void is discarded to start the timing, then all urine for 24 hours is collected (often kept cold) and the final void added."},
{cat:"specimens", q:"A fasting blood glucose specimen typically requires the patient to fast for:", choices:["2 to 4 hours","8 to 12 hours","24 hours","No fasting"], answer:1, why:"An 8 to 12 hour fast (water allowed) is standard so recent food intake does not falsely raise the glucose result."},
{cat:"specimens", q:"A glucose tolerance test (GTT) measures:", choices:["A single random glucose","Glucose at intervals after a glucose drink","Cholesterol","Kidney function"], answer:1, why:"The GTT checks how the body handles glucose by measuring blood glucose at timed intervals after a measured glucose load."},
{cat:"specimens", q:"The stool test that screens for hidden blood in the GI tract is the:", choices:["Urinalysis","Fecal occult blood test (FOBT)","Complete blood count","Lipid panel"], answer:1, why:"The FOBT (guaiac) test detects occult blood in stool, a screening tool for GI bleeding and colorectal cancer."},
{cat:"specimens", q:"A stool ova and parasites (O&P) test looks for:", choices:["Bacteria only","Parasites and their eggs","Blood","Glucose"], answer:1, why:"An O&P examines stool for parasites and their ova (eggs), often to investigate diarrhea or GI infection."},
{cat:"specimens", q:"A throat culture is collected to help diagnose:", choices:["A urinary tract infection","Streptococcal pharyngitis (strep throat)","Diabetes","Anemia"], answer:1, why:"A throat swab/culture identifies group A strep and other pharyngeal pathogens."},
{cat:"specimens", q:"When collecting a throat swab, the MA should swab the:", choices:["Tongue and lips","Tonsils and posterior pharynx, avoiding the tongue","Inner cheek only","Roof of the mouth only"], answer:1, why:"Swabbing the tonsillar areas and back of the throat captures pathogens; touching the tongue contaminates the sample."},
{cat:"specimens", q:"A urinalysis reagent (dipstick) strip can detect:", choices:["Only color","Glucose, protein, ketones, blood, pH, and more","Cholesterol","White blood cell count in blood"], answer:1, why:"The reagent strip performs chemical analysis for glucose, protein, ketones, blood, leukocytes, nitrites, pH, and others."},
{cat:"specimens", q:"Specific gravity of urine measures:", choices:["Acidity","The concentration of dissolved substances","Glucose only","Color"], answer:1, why:"Specific gravity reflects urine concentration (hydration and kidney concentrating ability)."},
{cat:"specimens", q:"A urine specimen that cannot be tested within 1 hour should be:", choices:["Left at room temperature","Refrigerated","Frozen solid","Discarded"], answer:1, why:"Refrigeration preserves a urine specimen if testing is delayed beyond about an hour, preventing bacterial overgrowth and chemical changes."},
{cat:"specimens", q:"Serum is obtained from blood that has:", choices:["An anticoagulant added","Been allowed to clot, then centrifuged","Been frozen","Been diluted"], answer:1, why:"Serum is the liquid remaining after blood clots and is centrifuged; plasma comes from anticoagulated blood that has not clotted."},
{cat:"specimens", q:"Plasma differs from serum in that plasma:", choices:["Contains clotting factors (fibrinogen)","Has no proteins","Is from clotted blood","Is the cell layer"], answer:0, why:"Plasma (from anticoagulated blood) still contains fibrinogen and clotting factors; serum does not because clotting has occurred."},
{cat:"specimens", q:"A centrifuge is used to:", choices:["Warm specimens","Separate blood components by spinning","Sterilize tubes","Count cells"], answer:1, why:"Centrifugation spins specimens at high speed to separate components such as serum or plasma from cells."},
{cat:"specimens", q:"For a balanced centrifuge, tubes should be:", choices:["Placed all on one side","Placed opposite each other with equal weight","Uncapped","Different sizes"], answer:1, why:"Tubes must be balanced opposite one another with equal volume/weight to prevent vibration and breakage."},
{cat:"specimens", q:"CLIA-waived tests are those that are:", choices:["Highly complex","Simple with a low risk of error","Performed only by pathologists","Banned in offices"], answer:1, why:"CLIA-waived tests are simple, low-risk procedures (e.g., dipstick urinalysis, rapid strep) that physician offices may perform."},
{cat:"specimens", q:"Quality control in the lab is performed to:", choices:["Increase billing","Ensure test results are accurate and reliable","Replace patient testing","Speed up draws"], answer:1, why:"Running controls verifies that equipment and reagents are working correctly so patient results can be trusted."},
{cat:"specimens", q:"Chain of custody is most important for which specimen?", choices:["Routine CBC","Forensic/drug-screen specimens","Throat culture","Random glucose"], answer:1, why:"Chain-of-custody documentation tracks a drug-screen or forensic specimen from collection to results to ensure legal integrity."},
{cat:"specimens", q:"A hemoglobin A1c test reflects average blood glucose over approximately:", choices:["1 day","2 to 3 months","1 week","1 year"], answer:1, why:"HbA1c reflects average glucose over the prior 2 to 3 months, used to monitor diabetes control."},
{cat:"specimens", q:"An erythrocyte sedimentation rate (ESR) is a nonspecific indicator of:", choices:["Blood sugar","Inflammation","Kidney stones","Cholesterol"], answer:1, why:"The ESR measures how fast red cells settle and rises with inflammation, though it does not pinpoint the cause."},
{cat:"specimens", q:"A urine pregnancy test detects which hormone?", choices:["Insulin","Human chorionic gonadotropin (hCG)","Estrogen only","Cortisol"], answer:1, why:"Pregnancy tests detect hCG, a hormone produced after implantation."},
{cat:"specimens", q:"A rapid strep test detects:", choices:["Influenza virus","Group A streptococcus antigen","Mononucleosis","Glucose"], answer:1, why:"The rapid strep test detects group A strep antigen from a throat swab; negatives are often confirmed by culture."},
{cat:"specimens", q:"PT/INR testing is used to monitor patients taking:", choices:["Insulin","Warfarin (an anticoagulant)","Antibiotics","Aspirin only"], answer:1, why:"PT/INR monitors the effect of warfarin and similar anticoagulants to keep clotting time in a safe range."},
{cat:"specimens", q:"A specimen may be rejected by the lab if it is:", choices:["Properly labeled","Hemolyzed, clotted, or mislabeled","Drawn in the correct tube","Transported promptly"], answer:1, why:"Hemolysis, clots in anticoagulant tubes, insufficient volume, or labeling errors are common reasons for specimen rejection."},
{cat:"specimens", q:"A microcollection (capillary) blood sample is appropriate when:", choices:["Large volumes are needed","Only a small volume is required, as in point-of-care glucose","Blood cultures are ordered","A full chemistry panel and CBC are needed"], answer:1, why:"Capillary sampling provides small volumes suitable for tests like glucose or hematocrit, not large-volume or culture testing."},
{cat:"specimens", q:"The evacuated tube system relies on:", choices:["Manual suction","A pre-set vacuum that draws a measured blood volume","Gravity only","Centrifugal force"], answer:1, why:"Each evacuated tube has a vacuum that pulls the correct blood volume once the needle enters the vein."},
{cat:"specimens", q:"A butterfly (winged infusion) set is especially useful for:", choices:["Very large veins","Small or fragile veins, such as in the hand","Arterial sticks","IV fluids only"], answer:1, why:"The butterfly set allows a shallower angle and better control for small, fragile, or hand veins."},
{cat:"specimens", q:"Selecting too small a needle gauge (very high number) for venipuncture can cause:", choices:["Faster flow","Hemolysis of the sample","No effect","Better veins"], answer:1, why:"A very small-bore needle forces cells through a narrow lumen and can hemolyze the specimen."},
{cat:"specimens", q:"If no blood enters the tube during venipuncture, the MA may have:", choices:["Used the correct vein","Missed the vein or gone through it","Filled the tube","Centrifuged too long"], answer:1, why:"No flow usually means the needle is not in the lumen (missed, too shallow, too deep, or against the wall); reposition gently or redraw."},
{cat:"specimens", q:"Blood cultures are drawn first in the order of draw to:", choices:["Save time","Maintain sterility and avoid contamination","Prevent clotting","Reduce pain"], answer:1, why:"Cultures are collected first using strict aseptic technique so the specimen is not contaminated by skin flora or other tubes."},
{cat:"specimens", q:"Before a blood culture, the venipuncture site is cleaned with:", choices:["Plain water","An antiseptic such as chlorhexidine or alcohol/iodine, allowed to dry","Hand sanitizer","Nothing"], answer:1, why:"Thorough antiseptic prep that is allowed to dry minimizes skin-flora contamination of the culture."},
{cat:"specimens", q:"A sputum specimen is best collected:", choices:["After eating","In the early morning, deep cough from the lungs","Right before bed","Only from saliva"], answer:1, why:"An early-morning deep cough yields true lower-respiratory sputum (not just saliva) for the best diagnostic yield."},
{cat:"specimens", q:"A wound culture should be collected:", choices:["After applying antibiotic ointment","Before cleaning or before antibiotics when possible","From dry, intact skin","Only after the wound heals"], answer:1, why:"Culturing before antiseptics/antibiotics gives a more accurate picture of the causative organisms."},
{cat:"specimens", q:"A point-of-care glucometer is an example of:", choices:["A high-complexity test","A CLIA-waived, point-of-care test","An imaging study","A coagulation analyzer"], answer:1, why:"Glucometers are simple, CLIA-waived, point-of-care devices used for rapid blood glucose results."},
{cat:"specimens", q:"To prevent additive carryover between tubes, the MA must:", choices:["Reverse the order of draw","Follow the correct order of draw","Use one tube for all tests","Shake each tube"], answer:1, why:"Following the standard order of draw prevents anticoagulant from one tube contaminating the next and skewing results."},
{cat:"specimens", q:"Fasting is generally required for which test?", choices:["CBC","Lipid panel","Blood type","Rapid strep"], answer:1, why:"A lipid panel typically requires fasting (often 9 to 12 hours) for accurate triglyceride measurement."},
{cat:"specimens", q:"A hematocrit measures:", choices:["The percentage of blood volume made of red cells","Blood glucose","Clotting time","White cell function"], answer:0, why:"Hematocrit is the proportion of blood volume occupied by red blood cells; low values may indicate anemia."},
{cat:"specimens", q:"Proper patient identification before a draw requires:", choices:["Asking the patient to state their name and date of birth","Calling out a room number","Checking only the chart","Recognizing the face"], answer:0, why:"Active identification, having the patient state name and DOB and matching it to the order, prevents wrong-patient errors."},
{cat:"specimens", q:"If a patient has an IV in one arm, blood should be drawn:", choices:["From the IV arm above the IV","From the opposite arm when possible","Through the IV line by the MA","Not at all"], answer:1, why:"Drawing from the opposite arm avoids IV-fluid dilution; the IV arm is used only with special precautions."},
{cat:"specimens", q:"A microscopic urinalysis examines for:", choices:["Color and clarity only","Cells, casts, crystals, and bacteria","Glucose strips","Specific gravity only"], answer:1, why:"The microscopic exam of centrifuged urine sediment identifies red/white cells, casts, crystals, and microorganisms."},
{cat:"specimens", q:"Ketones in the urine may indicate:", choices:["Normal hydration","Uncontrolled diabetes or fasting/starvation","High blood pressure","A urinary infection"], answer:1, why:"Ketones appear when the body burns fat for fuel, as in uncontrolled diabetes (DKA) or prolonged fasting."},
{cat:"specimens", q:"Protein in the urine (proteinuria) may suggest:", choices:["Healthy kidneys","Kidney disease or damage","Low blood sugar","Dehydration only"], answer:1, why:"Persistent protein in urine can indicate kidney damage and warrants further evaluation."},
{cat:"specimens", q:"Leukocytes and nitrites on a urine dipstick suggest:", choices:["Diabetes","A urinary tract infection","Liver disease","Anemia"], answer:1, why:"Leukocyte esterase and nitrites point toward a bacterial urinary tract infection."},
{cat:"specimens", q:"When transporting most blood specimens, they should be:", choices:["Shaken vigorously","Handled gently and kept per test requirements","Frozen immediately","Left open to air"], answer:1, why:"Gentle handling prevents hemolysis; storage temperature and timing follow each test's requirements."},
{cat:"specimens", q:"A medical assistant who is unsure how to collect an ordered specimen should:", choices:["Guess","Check the lab's specimen-collection manual or ask the provider","Skip the test","Use any tube"], answer:1, why:"Consulting the lab manual or provider ensures the right container, technique, and handling for accurate results."},
{cat:"specimens", q:"Newborn screening blood is most often collected by:", choices:["Antecubital venipuncture","Heel stick onto a filter-paper card","Arterial puncture","Urine collection"], answer:1, why:"Newborn metabolic screening uses heel-stick capillary blood applied to a filter-paper collection card."},
{cat:"specimens", q:"A medical assistant should put on gloves for venipuncture:", choices:["Only if the patient looks ill","Every time, as part of standard precautions","Never","Only for children"], answer:1, why:"Gloves are worn for every blood draw under standard precautions, since all blood is treated as potentially infectious."},
{cat:"specimens", q:"Underfilling a sodium citrate (light blue) tube will:", choices:["Have no effect","Cause an incorrect blood-to-additive ratio and inaccurate coagulation results","Improve accuracy","Speed clotting"], answer:1, why:"Coagulation tubes require a precise 9:1 fill; underfilling alters the ratio and invalidates PT/INR and PTT results."},
{cat:"specimens", q:"A capillary puncture should be made:", choices:["Parallel to the fingerprint lines","Perpendicular (across) the fingerprint lines","On the bone","On the nail"], answer:1, why:"Puncturing across (perpendicular to) the fingerprint grooves lets blood form a rounded drop instead of running along the lines."},
{cat:"specimens", q:"For a routine venipuncture, the site is most commonly cleaned with:", choices:["Plain water","70% isopropyl alcohol, allowed to air dry","Hydrogen peroxide","Betadine only"], answer:1, why:"Routine draws are cleaned with 70% isopropyl alcohol in a circular motion and allowed to air dry, so residual alcohol does not contaminate the sample or sting."},
{cat:"specimens", q:"The needle is typically inserted for venipuncture at an angle of:", choices:["15 to 30 degrees, bevel up","45 to 60 degrees, bevel down","90 degrees straight in","Parallel to the skin"], answer:0, why:"The needle enters bevel up at a shallow 15 to 30 degree angle following the vein, reducing the chance of going through the vein or causing injury."},

/* ========== Assisting with Physical Exams & Procedures (24) ========== */
{cat:"physexam", q:"A patient lying flat on the back, face up, is in the ____ position.", choices:["Prone","Supine","Sims","Lithotomy"], answer:1, why:"Supine means lying on the back, face up; it is used for many examinations and procedures."},
{cat:"physexam", q:"The prone position means the patient is lying:", choices:["On the back","Face down","On the left side","Sitting up"], answer:1, why:"Prone is lying face down, used to examine the back and spine."},
{cat:"physexam", q:"Fowler's position refers to a patient who is:", choices:["Lying face down","Sitting with the head of the table raised 45 to 60 degrees","Lying on the left side","Lying with feet elevated"], answer:1, why:"Fowler's position is semi-sitting with the backrest elevated about 45 to 60 degrees, easing breathing and head/chest exams."},
{cat:"physexam", q:"The lithotomy position is used primarily for:", choices:["Back exams","Pelvic and vaginal examinations","Ear exams","Spinal taps"], answer:1, why:"In lithotomy, the patient lies supine with feet in stirrups for gynecologic, pelvic, and urologic examinations."},
{cat:"physexam", q:"The Sims position (left side, right knee drawn up) is used for:", choices:["Eye exams","Rectal exams and enemas","Chest exams","Standing balance tests"], answer:1, why:"The Sims (left lateral) position is used for rectal examinations, enemas, and some perineal procedures."},
{cat:"physexam", q:"The Trendelenburg position places the patient:", choices:["Sitting upright","Supine with the head lower than the feet","Face down","On the right side"], answer:1, why:"In Trendelenburg, the body is supine and tilted so the head is lower than the feet, sometimes used for certain procedures or shock."},
{cat:"physexam", q:"Before the provider examines a patient, the MA should:", choices:["Diagnose the complaint","Prepare the room, position and drape the patient, and ready the equipment","Prescribe medication","Bill the visit"], answer:1, why:"The MA readies the room and equipment, positions and drapes the patient for privacy, and documents, supporting but not performing the exam."},
{cat:"physexam", q:"Draping a patient during an exam is done primarily to:", choices:["Keep the room clean","Provide privacy and warmth and expose only the area being examined","Speed up the visit","Replace a gown"], answer:1, why:"Draping protects the patient's dignity and comfort by exposing only the area under examination."},
{cat:"physexam", q:"To maintain a sterile field during a procedure, the MA should:", choices:["Reach across it","Keep sterile items in view and above waist level","Turn their back to it","Talk and cough over it"], answer:1, why:"A sterile field must stay in view and above the waist and must never be reached across or contaminated."},
{cat:"physexam", q:"The 1-inch outer border of a sterile drape is considered:", choices:["Sterile","Contaminated (nonsterile)","Optional","The cleanest area"], answer:1, why:"The outer 1-inch margin of a sterile field is treated as nonsterile and should not hold sterile items."},
{cat:"physexam", q:"The instrument used to examine the ear canal and eardrum is the:", choices:["Ophthalmoscope","Otoscope","Stethoscope","Sphygmomanometer"], answer:1, why:"An otoscope visualizes the ear canal and tympanic membrane; the ophthalmoscope is used for the eye."},
{cat:"physexam", q:"The instrument used to examine the interior of the eye is the:", choices:["Otoscope","Ophthalmoscope","Speculum","Percussion hammer"], answer:1, why:"The ophthalmoscope lets the provider view the retina and inner structures of the eye."},
{cat:"physexam", q:"A Snellen chart is used to assess:", choices:["Hearing","Distance visual acuity","Color blindness","Blood pressure"], answer:1, why:"The Snellen chart measures distance visual acuity, typically read from 20 feet away."},
{cat:"physexam", q:"The examination technique of listening with a stethoscope is called:", choices:["Palpation","Auscultation","Percussion","Inspection"], answer:1, why:"Auscultation is listening to body sounds (heart, lungs, bowel) with a stethoscope."},
{cat:"physexam", q:"The examination technique of feeling with the hands is called:", choices:["Auscultation","Palpation","Percussion","Mensuration"], answer:1, why:"Palpation uses touch to assess texture, size, tenderness, and masses."},
{cat:"physexam", q:"Percussion during a physical exam involves:", choices:["Looking at the skin","Tapping body surfaces to assess underlying structures","Listening with a stethoscope","Measuring height"], answer:1, why:"Percussion taps the body and interprets the resulting sounds to evaluate underlying organs or cavities."},
{cat:"physexam", q:"A vaginal speculum is used during which examination?", choices:["Ear","Pelvic/gynecologic","Throat","Rectal only"], answer:1, why:"A speculum holds the vaginal walls open during a pelvic exam and Pap collection."},
{cat:"physexam", q:"A Pap smear is collected to screen for:", choices:["Diabetes","Cervical cancer/abnormal cervical cells","Pregnancy","Anemia"], answer:1, why:"The Pap test screens for cervical cancer and precancerous cell changes."},
{cat:"physexam", q:"When assisting with a procedure, the MA's role includes:", choices:["Making the diagnosis","Anticipating the provider's needs and handing instruments","Signing the consent for the patient","Choosing the medication"], answer:1, why:"The MA supports the provider by preparing/handing instruments, comforting the patient, and documenting, not by diagnosing or consenting for the patient."},
{cat:"physexam", q:"Informed consent for a procedure should be obtained:", choices:["After the procedure","Before the procedure, by the provider","By the receptionist","Only if there is a complication"], answer:1, why:"The provider obtains informed consent before the procedure; the MA may witness the signature but does not explain risks."},
{cat:"physexam", q:"Proper body mechanics when assisting a patient include:", choices:["Bending at the waist","Bending the knees and keeping the back straight","Twisting while lifting","Holding the load far from the body"], answer:1, why:"Lifting with the legs, keeping the back straight, and holding loads close prevents injury."},
{cat:"physexam", q:"Before a procedure, surgical instruments arranged on a tray should be:", choices:["Used straight from the package without checking","Sterile, complete, and arranged in order of use","Shared between patients","Left uncovered overnight"], answer:1, why:"Instruments must be sterile, accounted for, and logically arranged so the provider can work efficiently."},
{cat:"physexam", q:"After a minor surgical procedure, used instruments should be:", choices:["Returned to the drawer","Cleaned/sanitized, then disinfected or sterilized as required","Thrown in the trash","Rinsed and reused immediately"], answer:1, why:"Reusable instruments are first sanitized to remove debris, then disinfected or sterilized per their classification before reuse."},
{cat:"physexam", q:"Measuring a patient's height and weight is an example of:", choices:["Auscultation","Mensuration","Percussion","Palpation"], answer:1, why:"Mensuration is the process of measuring (e.g., height, weight, circumference) during patient assessment."},

/* ========== Administration of Medications (21) ========== */
{cat:"meds", q:"The 'six rights' of medication administration include right patient, drug, dose, route, time, and right:", choices:["Color","Documentation","Price","Temperature"], answer:1, why:"The sixth right is documentation, accurately recording the medication after it is given."},
{cat:"meds", q:"An intramuscular (IM) injection is administered at a ____ angle.", choices:["15 degrees","45 degrees","90 degrees","10 degrees"], answer:2, why:"IM injections are given at 90 degrees to reach muscle tissue; subcutaneous injections use 45 degrees (or 90 with a short needle)."},
{cat:"meds", q:"A subcutaneous injection is typically given at a ____ angle.", choices:["10 degrees","45 degrees","90 degrees","15 degrees"], answer:1, why:"Subcutaneous injections deposit medication into fatty tissue at a 45 degree angle (90 with a short insulin needle)."},
{cat:"meds", q:"An intradermal injection (e.g., a TB test) is given at a ____ angle.", choices:["10 to 15 degrees","45 degrees","90 degrees","60 degrees"], answer:0, why:"Intradermal injections are placed just under the skin at a shallow 10 to 15 degree angle, raising a small wheal."},
{cat:"meds", q:"The abbreviation 'PO' on a medication order means the drug is given:", choices:["Topically","By mouth","Into a vein","Under the skin"], answer:1, why:"PO (per os) means by mouth / orally."},
{cat:"meds", q:"The abbreviation 'bid' means the medication is taken:", choices:["Once a day","Twice a day","Three times a day","At bedtime"], answer:1, why:"bid (bis in die) means twice a day; tid is three times and qid is four times daily."},
{cat:"meds", q:"The abbreviation 'tid' means:", choices:["Twice a day","Three times a day","Four times a day","Every hour"], answer:1, why:"tid (ter in die) means three times a day."},
{cat:"meds", q:"The abbreviation 'PRN' means the medication is given:", choices:["At bedtime","As needed","Before meals","By injection"], answer:1, why:"PRN (pro re nata) means the medication is given as needed for a specified condition."},
{cat:"meds", q:"The abbreviation 'ac' means:", choices:["After meals","Before meals","At bedtime","With water"], answer:1, why:"ac (ante cibum) means before meals; pc (post cibum) means after meals."},
{cat:"meds", q:"The deltoid muscle is a common site for:", choices:["IV fluids","Intramuscular injections such as vaccines","Oral medication","Only insulin"], answer:1, why:"The deltoid (upper arm) is a common intramuscular site for adult vaccines."},
{cat:"meds", q:"The preferred IM injection site in infants is the:", choices:["Deltoid","Vastus lateralis (thigh)","Dorsogluteal","Abdomen"], answer:1, why:"The vastus lateralis (anterolateral thigh) is the recommended IM site in infants due to its muscle mass and safety."},
{cat:"meds", q:"Before administering any medication, the MA must always check the patient's:", choices:["Favorite color","Allergies","Insurance copay","Home address"], answer:1, why:"Verifying allergies before administration helps prevent potentially life-threatening reactions."},
{cat:"meds", q:"The medication label should be checked how many times before administration?", choices:["Once","Three times","Never","Only if unsure"], answer:1, why:"The label is checked three times: when taking it from storage, when preparing it, and before returning/administering, to prevent errors."},
{cat:"meds", q:"The sublingual route means the medication is placed:", choices:["On the skin","Under the tongue","In the rectum","In the muscle"], answer:1, why:"Sublingual medications dissolve under the tongue and are absorbed through the oral mucosa (e.g., nitroglycerin)."},
{cat:"meds", q:"The topical route delivers medication:", choices:["Into a vein","Onto the skin or mucous membranes","Into a muscle","By mouth"], answer:1, why:"Topical medications are applied to the skin or mucous membranes for local (or sometimes systemic) effect."},
{cat:"meds", q:"A 'Z-track' technique is used for IM injections to:", choices:["Speed absorption","Prevent medication from leaking back into subcutaneous tissue","Reduce the dose","Avoid using a needle"], answer:1, why:"The Z-track method displaces the skin so the needle track seals after withdrawal, keeping irritating medication in the muscle."},
{cat:"meds", q:"Insulin is most commonly administered by which route?", choices:["Oral","Subcutaneous","Intramuscular","Intradermal"], answer:1, why:"Insulin is given subcutaneously because oral insulin would be destroyed by digestion."},
{cat:"meds", q:"Which equivalent is correct?", choices:["1 teaspoon = 5 mL","1 teaspoon = 15 mL","1 tablespoon = 5 mL","1 ounce = 5 mL"], answer:0, why:"One teaspoon equals about 5 mL; one tablespoon equals about 15 mL; one ounce equals about 30 mL."},
{cat:"meds", q:"If a medication order is unclear or seems incorrect, the MA should:", choices:["Give a best guess","Clarify with the provider before administering","Ask another patient","Skip documentation"], answer:1, why:"An unclear or questionable order must be clarified with the prescriber before any medication is given."},
{cat:"meds", q:"After giving an injection, the syringe and needle should be:", choices:["Recapped by hand","Placed uncapped into a sharps container","Reused for the next patient","Thrown in the trash"], answer:1, why:"The used sharp goes immediately, without recapping, into a puncture-proof sharps container."},
{cat:"meds", q:"Documentation of a medication should include the drug, dose, route, time, and:", choices:["The patient's favorite snack","Site (for injections) and the MA's signature/initials","The weather","Nothing else"], answer:1, why:"Complete documentation records drug, dose, route, time, injection site, and who administered it."},

/* ========== Patient Intake (15) ========== */
{cat:"intake", q:"The average normal adult oral body temperature is about:", choices:["97.0 F","98.6 F","99.8 F","100.4 F"], answer:1, why:"Average normal oral temperature is 98.6 F (37 C), with a normal range of roughly 97 to 99 F."},
{cat:"intake", q:"A normal resting heart rate for an adult is:", choices:["40 to 60 bpm","60 to 100 bpm","100 to 120 bpm","120 to 140 bpm"], answer:1, why:"A normal adult resting pulse is 60 to 100 beats per minute."},
{cat:"intake", q:"A normal adult respiratory rate at rest is:", choices:["6 to 10 breaths/min","12 to 20 breaths/min","24 to 30 breaths/min","30 to 40 breaths/min"], answer:1, why:"Normal adult respirations are 12 to 20 breaths per minute at rest."},
{cat:"intake", q:"In a blood pressure of 118/76, the number 76 represents the:", choices:["Systolic pressure","Diastolic pressure","Pulse pressure","Heart rate"], answer:1, why:"The bottom number is the diastolic pressure, the arterial pressure while the heart rests between beats."},
{cat:"intake", q:"In a blood pressure reading, the systolic number reflects pressure when the:", choices:["Heart rests","Ventricles contract","Atria fill","Patient exhales"], answer:1, why:"Systolic pressure is the higher number, measured when the ventricles contract and eject blood."},
{cat:"intake", q:"The pulse point on the thumb side of the wrist is the:", choices:["Carotid pulse","Radial pulse","Femoral pulse","Apical pulse"], answer:1, why:"The radial pulse is palpated on the thumb (lateral) side of the wrist over the radial artery."},
{cat:"intake", q:"The apical pulse is auscultated:", choices:["At the wrist","Over the apex of the heart with a stethoscope","In the neck","Behind the knee"], answer:1, why:"The apical pulse is heard with a stethoscope over the heart's apex and is preferred for infants and irregular rhythms."},
{cat:"intake", q:"The 'chief complaint' recorded during intake is:", choices:["The provider's diagnosis","The patient's main reason for the visit, in their own words","The billing code","The medication list"], answer:1, why:"The chief complaint is the patient's primary reason for the visit, documented in their own words."},
{cat:"intake", q:"An oxygen saturation (SpO2) reading is obtained using a:", choices:["Thermometer","Pulse oximeter","Sphygmomanometer","Glucometer"], answer:1, why:"A pulse oximeter clips on a finger (or ear) to measure the percentage of oxygen-saturated hemoglobin."},
{cat:"intake", q:"A normal oxygen saturation (SpO2) for a healthy adult is generally:", choices:["70 to 80 percent","95 to 100 percent","50 to 60 percent","85 to 88 percent"], answer:1, why:"Normal SpO2 is about 95 to 100 percent on room air; lower values may indicate hypoxemia."},
{cat:"intake", q:"For an accurate blood pressure, the cuff should be:", choices:["Too small for the arm","The correct size, about 80 percent of the arm circumference","Placed over clothing","On the wrist always"], answer:1, why:"A correctly sized cuff (bladder about 80 percent of arm circumference) on a bare arm gives accurate readings; a too-small cuff reads falsely high."},
{cat:"intake", q:"While taking vital signs, the patient should ideally be:", choices:["Walking","Seated and rested for several minutes","Talking on the phone","Lying face down"], answer:1, why:"A rested, seated patient who refrains from talking gives more accurate vital signs, especially blood pressure and pulse."},
{cat:"intake", q:"Reviewing and updating the patient's medication list at intake is important because:", choices:["It increases billing","It helps prevent interactions and informs the provider","It is optional","Patients enjoy it"], answer:1, why:"An accurate, current medication list (medication reconciliation) helps prevent drug interactions and supports safe care."},
{cat:"intake", q:"Pain is often assessed at intake using a:", choices:["Snellen chart","0 to 10 numeric pain scale","Glucometer","Stethoscope"], answer:1, why:"A 0 to 10 numeric (or faces) scale lets patients rate pain intensity, which is documented as part of intake."},
{cat:"intake", q:"When rooming a patient, the MA should:", choices:["Discuss other patients","Verify identity, record vitals and chief complaint, and update history","Diagnose the problem","Prescribe treatment"], answer:1, why:"Rooming includes identifying the patient, taking vital signs, recording the chief complaint, and updating history/medications for the provider."},

/* ========== Office Reception (18) ========== */
{cat:"reception", q:"Booking several patients to arrive at the start of the same hour and be seen in order is called:", choices:["Wave scheduling","Stream scheduling","Open booking","Cluster scheduling"], answer:0, why:"Wave scheduling books multiple patients at the top of the hour to be seen in order of arrival, smoothing patient flow."},
{cat:"reception", q:"Scheduling one patient at each set time slot is called:", choices:["Wave scheduling","Stream (time-specified) scheduling","Double booking","Open hours"], answer:1, why:"Stream scheduling gives each patient an individual appointment time, the most common method."},
{cat:"reception", q:"Grouping similar appointments together (e.g., all physicals in one block) is called:", choices:["Cluster scheduling","Double booking","Open booking","Wave scheduling"], answer:0, why:"Cluster (grouping) scheduling batches similar visit types together for efficiency."},
{cat:"reception", q:"A patient who fails to arrive for an appointment without calling is documented as a:", choices:["Cancellation","No-show","Walk-in","Referral"], answer:1, why:"A no-show is recorded in the chart when a patient neither arrives nor cancels, important for legal and scheduling reasons."},
{cat:"reception", q:"A patient who arrives without an appointment is a:", choices:["No-show","Walk-in","Referral","Cancellation"], answer:1, why:"A walk-in arrives without a prior appointment and is worked into the schedule per office policy."},
{cat:"reception", q:"At the front desk, the MA best protects privacy by:", choices:["Announcing full names and diagnoses","Not discussing health information where others can overhear","Leaving charts open on the counter","Reading the schedule aloud"], answer:1, why:"Protecting PHI at reception (a HIPAA requirement) means not revealing health details where other patients can hear."},
{cat:"reception", q:"A patient phones reporting severe chest pain and shortness of breath. The MA should:", choices:["Schedule a routine visit next week","Recognize a possible emergency and follow protocol, directing them to 911","Take a message for later","Transfer the call to billing"], answer:1, why:"Chest pain with shortness of breath is potentially life-threatening; follow the office emergency protocol and direct the patient to emergency care/911."},
{cat:"reception", q:"Sorting incoming calls by urgency is called:", choices:["Billing","Telephone triage","Coding","Filing"], answer:1, why:"Telephone triage prioritizes calls by clinical urgency so emergencies are handled first."},
{cat:"reception", q:"When answering the office phone, the MA should:", choices:["Put every caller on hold immediately","Identify the office and themselves and speak courteously","Eat while talking","Give out test results freely"], answer:1, why:"Professional phone etiquette starts with identifying the practice and yourself and assisting the caller courteously."},
{cat:"reception", q:"Before placing a caller on hold, the MA should:", choices:["Just press hold","Ask permission and wait for a response","Hang up","Transfer without asking"], answer:1, why:"Always ask the caller's permission before placing them on hold and check back if the wait is long."},
{cat:"reception", q:"A new patient typically needs more appointment time than an established patient because:", choices:["They pay more","A full history and registration must be completed","They always need labs","It is required by law"], answer:1, why:"New patients require complete registration, history, and insurance setup, so more time is allotted."},
{cat:"reception", q:"The appointment matrix is:", choices:["A billing form","The blocked-out template showing available and unavailable times","A patient chart","An insurance card"], answer:1, why:"The matrix marks times the provider is unavailable (lunch, meetings, holidays) so only open slots are booked."},
{cat:"reception", q:"When a patient checks in, the MA should verify:", choices:["Only the name","Identity, demographics, and insurance information","The weather","Their favorite color"], answer:1, why:"Confirming identity, current demographics, and insurance at check-in keeps records accurate and supports correct billing."},
{cat:"reception", q:"A reminder call or text the day before an appointment helps to:", choices:["Increase no-shows","Reduce no-shows","Replace the visit","Bill insurance"], answer:1, why:"Appointment reminders reduce no-shows and help patients keep their scheduled visits."},
{cat:"reception", q:"Greeting patients warmly and making eye contact is part of:", choices:["Billing","Good customer service and professionalism","Coding","Triage"], answer:1, why:"A courteous, welcoming reception sets a positive tone and reflects professionalism."},
{cat:"reception", q:"When the reception area has a long wait, the MA should:", choices:["Ignore waiting patients","Acknowledge the delay and keep patients informed","Argue with patients","Hide the schedule"], answer:1, why:"Keeping patients informed about delays shows respect and reduces frustration."},
{cat:"reception", q:"Patient sign-in sheets that display other patients' names may violate:", choices:["OSHA","Patient privacy (HIPAA)","CPR guidelines","CLIA"], answer:1, why:"Sign-in methods that reveal other patients' identities/conditions can breach privacy; offices use privacy-protective sign-in."},
{cat:"reception", q:"If two patients arrive at once and one is having difficulty breathing, the MA should:", choices:["Take them in order of arrival","Prioritize the patient in respiratory distress","Ask them to decide","Call billing"], answer:1, why:"Triage means the more acute patient (difficulty breathing) is seen first regardless of arrival order."},

/* ========== Medical Record Management (18) ========== */
{cat:"records", q:"The acronym EHR stands for:", choices:["Emergency Health Report","Electronic Health Record","Extended Hospital Record","Electronic Hospital Referral"], answer:1, why:"EHR stands for Electronic Health Record, the digital version of a patient's chart."},
{cat:"records", q:"In a SOAP note, the 'O' stands for:", choices:["Opinion","Objective","Order","Outcome"], answer:1, why:"SOAP = Subjective, Objective, Assessment, Plan; Objective is measurable data such as vital signs and exam findings."},
{cat:"records", q:"In a SOAP note, the 'S' (Subjective) includes:", choices:["Vital signs","What the patient reports, such as symptoms","Lab results","The diagnosis"], answer:1, why:"Subjective data is what the patient states (symptoms, history), as opposed to measurable objective findings."},
{cat:"records", q:"In a SOAP note, the 'A' stands for:", choices:["Assessment (the diagnosis/impression)","Action","Appointment","Allergy"], answer:0, why:"Assessment is the provider's diagnosis or clinical impression based on subjective and objective data."},
{cat:"records", q:"Who owns the physical medical record?", choices:["The patient","The healthcare provider or practice","The insurance company","The state"], answer:1, why:"The provider/practice owns the physical record, while the patient owns the information in it and has the right to access it."},
{cat:"records", q:"The correct way to fix an error in a paper medical record is to:", choices:["Erase the error","Use correction fluid","Draw a single line through it, then initial and date the correction","Remove the page"], answer:2, why:"Draw a single line through the error so it stays legible, write the correction, and initial and date it, never erase or obliterate."},
{cat:"records", q:"Charting should be done:", choices:["At the end of the week","Promptly and accurately after care is given","Only when convenient","By the patient"], answer:1, why:"Timely, accurate documentation ensures the record reflects care actually provided and supports continuity and legal protection."},
{cat:"records", q:"The phrase 'if it was not documented, it was not done' emphasizes that:", choices:["Documentation is optional","The record is the legal proof of care provided","Charts can be vague","Memory is enough"], answer:1, why:"The medical record is the legal evidence of care; undocumented care is treated as if it did not occur."},
{cat:"records", q:"Filing records by the patient's last name is an example of:", choices:["Numeric filing","Alphabetic filing","Color coding only","Subject filing"], answer:1, why:"Alphabetic filing organizes records by last name, then first name and middle initial."},
{cat:"records", q:"In numeric filing, records are organized by:", choices:["Last name","An assigned number (e.g., medical record number)","Date of visit only","Diagnosis"], answer:1, why:"Numeric filing uses an assigned patient number and can enhance confidentiality compared with names."},
{cat:"records", q:"A problem-oriented medical record (POMR) is organized around:", choices:["The provider's schedule","The patient's specific problems","Billing codes","Insurance plans"], answer:1, why:"The POMR lists the patient's problems and documents care under each, improving tracking of ongoing issues."},
{cat:"records", q:"Objective data in the record includes:", choices:["The patient's complaint of pain","Measured vital signs and exam findings","The patient's feelings","Family rumors"], answer:1, why:"Objective data is measurable and observable, such as vital signs, lab values, and physical exam findings."},
{cat:"records", q:"Medical records should be retained:", choices:["For one week","According to state and federal retention laws","Forever in the waiting room","Only until the next visit"], answer:1, why:"Retention periods are set by state and federal law (often several years; longer for minors); offices follow these requirements."},
{cat:"records", q:"When a patient requests a copy of their record, the office should:", choices:["Refuse","Provide it following HIPAA procedures and any required authorization","Give it to anyone who asks","Charge an illegal fee"], answer:1, why:"Patients have a right to access their records; the office releases them following HIPAA and office policy."},
{cat:"records", q:"An advantage of an EHR over paper records is:", choices:["Easier to lose","Improved legibility, access, and decision support","No backups needed","Less secure by design"], answer:1, why:"EHRs improve legibility, simultaneous access, clinical decision support, and data sharing when properly secured."},
{cat:"records", q:"Backing up electronic health records is important to:", choices:["Increase clutter","Protect against data loss from system failure","Avoid using computers","Slow the office"], answer:1, why:"Regular backups protect critical patient data against hardware failure, ransomware, or disasters."},
{cat:"records", q:"Audit trails in an EHR record:", choices:["Only billing","Who accessed or changed a record and when","The weather","Appointment colors"], answer:1, why:"Audit trails log user access and changes, supporting security, accountability, and HIPAA compliance."},
{cat:"records", q:"A release of information form is needed to:", choices:["Schedule a visit","Disclose a patient's records to a third party","Take vital signs","Order supplies"], answer:1, why:"A signed authorization (release of information) is generally required before disclosing records to outside parties."},

/* ========== Patient Care Coordination & Education (9) ========== */
{cat:"coordination", q:"The MA can best confirm a patient understood instructions by:", choices:["Handing them a brochure and leaving","Using teach-back, having the patient explain it in their own words","Speaking in medical jargon","Telling them not to ask questions"], answer:1, why:"The teach-back method confirms understanding by having the patient restate the instructions, improving adherence and safety."},
{cat:"coordination", q:"A 'referral' in care coordination is:", choices:["A bill sent to insurance","Directing a patient to a specialist or additional service","A medication order","A lab result"], answer:1, why:"A referral connects the patient to a specialist or additional service and is often required by insurance for coverage."},
{cat:"coordination", q:"When educating a patient with limited English proficiency, the MA should:", choices:["Speak louder","Use a qualified medical interpreter","Have a child translate sensitive details","Skip the teaching"], answer:1, why:"A qualified interpreter ensures accurate, confidential communication; family members (especially children) are not appropriate for medical interpreting."},
{cat:"coordination", q:"Effective patient education materials should be:", choices:["Highly technical","Written at an appropriate, easy-to-understand reading level","Only in medical jargon","Verbal only"], answer:1, why:"Education materials at a suitable reading level improve comprehension and health literacy."},
{cat:"coordination", q:"Care coordination for a patient with multiple specialists helps to:", choices:["Duplicate tests","Ensure communication and avoid gaps or conflicts in care","Increase confusion","Replace the primary provider"], answer:1, why:"Coordinating among providers reduces duplicate testing and conflicting plans and keeps everyone informed."},
{cat:"coordination", q:"Before teaching a patient, the MA should first:", choices:["Assume they know nothing","Assess the patient's current knowledge and learning needs","Read the entire textbook","Skip to the test"], answer:1, why:"Assessing what the patient already knows and their barriers lets the MA tailor effective education."},
{cat:"coordination", q:"A patient navigator or care coordinator may help patients by:", choices:["Diagnosing illnesses","Arranging appointments, resources, and follow-up","Prescribing drugs","Performing surgery"], answer:1, why:"Care coordinators help patients access services, schedule follow-up, and overcome barriers to care."},
{cat:"coordination", q:"When giving discharge or follow-up instructions, the MA should:", choices:["Give them only verbally and quickly","Provide clear written and verbal instructions and confirm understanding","Assume the patient remembers everything","Use abbreviations only"], answer:1, why:"Combining written and verbal instructions with teach-back improves adherence and reduces errors after the visit."},
{cat:"coordination", q:"Health literacy refers to a patient's ability to:", choices:["Read medical journals","Obtain, understand, and use health information to make decisions","Bill insurance","Operate an autoclave"], answer:1, why:"Health literacy is the capacity to understand and act on health information; low literacy requires plain-language teaching."},

/* ========== Billing & Insurance (21) ========== */
{cat:"billing", q:"The standard claim form used to bill physician and outpatient services is the:", choices:["UB-04","CMS-1500","W-2","SOAP form"], answer:1, why:"The CMS-1500 is the standard claim form for physician/outpatient services; the UB-04 is used for facility/inpatient claims."},
{cat:"billing", q:"A 'copayment' is:", choices:["The total bill","A fixed amount the patient pays per visit or service","The insurer's payment","A yearly premium"], answer:1, why:"A copay is a set dollar amount the patient pays at the time of service, such as $25 per office visit."},
{cat:"billing", q:"A 'deductible' is:", choices:["A discount for paying cash","The amount the patient must pay before insurance begins paying","The copay amount","A tax form"], answer:1, why:"The deductible is the amount the patient pays out of pocket each year before the insurer starts covering costs."},
{cat:"billing", q:"'Coinsurance' is:", choices:["A flat fee","A percentage of the cost the patient shares after the deductible","The premium","A type of claim form"], answer:1, why:"Coinsurance is the patient's percentage share of covered costs (e.g., 20 percent) after meeting the deductible."},
{cat:"billing", q:"A 'premium' is:", choices:["A fee paid (often monthly) to keep insurance coverage","The same as a copay","Paid only when sick","A claim form"], answer:0, why:"The premium is the regular (often monthly) payment to maintain insurance coverage, separate from copays/deductibles."},
{cat:"billing", q:"ICD-10 codes report ____, while CPT codes report ____.", choices:["procedures; diagnoses","diagnoses; procedures","drugs; supplies","providers; patients"], answer:1, why:"ICD-10 codes describe diagnoses (the why); CPT codes describe the procedures and services performed (the what)."},
{cat:"billing", q:"CPT codes are maintained by the:", choices:["FDA","American Medical Association (AMA)","OSHA","CDC"], answer:1, why:"The AMA maintains Current Procedural Terminology (CPT) codes for procedures and services."},
{cat:"billing", q:"Medicare Part A primarily covers:", choices:["Prescription drugs","Hospital and inpatient care","Routine dental","Vision exams"], answer:1, why:"Part A covers inpatient hospital, skilled nursing, and hospice care; Part B covers outpatient/physician services; Part D covers drugs."},
{cat:"billing", q:"Medicare Part B primarily covers:", choices:["Inpatient hospital stays","Outpatient and physician services","Prescription drugs","Long-term custodial care"], answer:1, why:"Part B covers physician services, outpatient care, and preventive services."},
{cat:"billing", q:"Medicare Part D covers:", choices:["Hospital care","Prescription drugs","Emergency room only","Dental"], answer:1, why:"Medicare Part D provides prescription drug coverage."},
{cat:"billing", q:"Medicaid is a program that provides coverage based primarily on:", choices:["Age 65+","Low income/financial need","Military service","Employment status only"], answer:1, why:"Medicaid is a joint federal-state program covering eligible low-income individuals and families."},
{cat:"billing", q:"Precertification (prior authorization) is:", choices:["A patient's bill","Insurer approval obtained before certain services","A diagnosis code","A type of copay"], answer:1, why:"Prior authorization is approval from the insurer before a service to confirm coverage; without it, claims may be denied."},
{cat:"billing", q:"An explanation of benefits (EOB) is:", choices:["A claim form","A statement from the insurer explaining what was paid and what the patient owes","A prescription","A referral"], answer:1, why:"The EOB details how the insurer processed a claim, including allowed amounts, payments, and patient responsibility."},
{cat:"billing", q:"A claim may be denied if:", choices:["It is coded correctly","Information is missing, codes are wrong, or coverage lapsed","The patient is insured","Prior authorization was obtained"], answer:1, why:"Errors such as missing data, incorrect codes, or eligibility/coverage problems are common reasons for claim denials."},
{cat:"billing", q:"A 'fee-for-service' model means the provider is paid:", choices:["A flat monthly amount per patient","For each service provided","Only by the patient","Nothing"], answer:1, why:"Fee-for-service reimburses the provider for each individual service rendered."},
{cat:"billing", q:"In a capitation model, the provider is paid:", choices:["Per service","A set amount per enrolled patient per period","Only for surgeries","By the hour"], answer:1, why:"Capitation pays a fixed amount per enrolled patient per month regardless of services used."},
{cat:"billing", q:"An HMO typically requires patients to:", choices:["See any provider freely","Use in-network providers and often get referrals","Pay all costs out of pocket","Avoid primary care"], answer:1, why:"HMOs emphasize in-network care and often require referrals from a primary care provider."},
{cat:"billing", q:"A 'superbill' (encounter form) lists:", choices:["The patient's address only","Services, diagnoses, and charges for a visit","Staff schedules","Inventory"], answer:1, why:"The superbill itemizes the diagnoses (ICD) and procedures (CPT) with charges to generate the insurance claim."},
{cat:"billing", q:"Accounts receivable refers to:", choices:["Money the practice owes others","Money owed TO the practice for services","Office supplies","Employee wages"], answer:1, why:"Accounts receivable is income owed to the practice by patients and insurers for services already provided."},
{cat:"billing", q:"Upcoding (billing for a more expensive service than performed) is:", choices:["Good practice","Fraudulent and illegal","Required by Medicare","A type of referral"], answer:1, why:"Upcoding misrepresents services to obtain higher payment and is billing fraud."},
{cat:"billing", q:"Verifying a patient's insurance eligibility before the visit helps to:", choices:["Delay care","Confirm coverage and reduce claim denials","Avoid documentation","Skip billing"], answer:1, why:"Eligibility verification confirms active coverage and benefits, reducing denied claims and surprise patient costs."},

/* ========== Medical Office Management (12) ========== */
{cat:"management", q:"The OSHA-required document detailing a chemical's hazards and safe handling is the:", choices:["CMS-1500","Safety Data Sheet (SDS)","SOAP note","Referral form"], answer:1, why:"The Safety Data Sheet (SDS, formerly MSDS) lists chemical hazards, handling, and first aid and must be accessible to staff."},
{cat:"management", q:"Monitoring stock levels, expiration dates, and reordering supplies is part of:", choices:["Coding","Inventory management","Triage","Phlebotomy"], answer:1, why:"Inventory management, tracking stock, checking expiration dates, and reordering, is a routine office management duty."},
{cat:"management", q:"CLIA regulations govern:", choices:["Building codes","Laboratory testing quality","Parking","Advertising"], answer:1, why:"The Clinical Laboratory Improvement Amendments (CLIA) set standards to ensure quality and accuracy of lab testing."},
{cat:"management", q:"OSHA is the federal agency responsible for:", choices:["Drug approval","Workplace safety and health","Medical coding","Insurance claims"], answer:1, why:"The Occupational Safety and Health Administration sets and enforces workplace safety standards."},
{cat:"management", q:"A policy and procedures manual exists to:", choices:["Decorate the office","Standardize operations and guide staff","Replace training","Bill patients"], answer:1, why:"The manual documents how tasks are performed, promoting consistency, safety, and compliance."},
{cat:"management", q:"Equipment such as an autoclave should be maintained by:", choices:["Ignoring it until it breaks","Following a routine maintenance and testing schedule","Using it without checks","Replacing it weekly"], answer:1, why:"Scheduled maintenance and testing (including spore tests for autoclaves) keep equipment safe and reliable."},
{cat:"management", q:"An incident report should be completed when:", choices:["A patient is happy","An accident, injury, or unusual event occurs","A claim is paid","Supplies are ordered"], answer:1, why:"Incident reports document accidents, injuries, or errors for risk management and quality improvement."},
{cat:"management", q:"Expired medications and supplies should be:", choices:["Used anyway","Removed from stock and properly discarded","Given to patients","Hidden"], answer:1, why:"Expired items are removed and disposed of properly to ensure patient safety and regulatory compliance."},
{cat:"management", q:"Petty cash in a medical office is used for:", choices:["Paying salaries","Small, incidental expenses","Patient refunds only","Insurance premiums"], answer:1, why:"Petty cash covers minor incidental purchases and is tracked with receipts and a log."},
{cat:"management", q:"Cross-training staff in multiple roles helps the office by:", choices:["Reducing flexibility","Providing coverage when someone is absent","Increasing errors","Eliminating teamwork"], answer:1, why:"Cross-trained staff can cover for absences and peaks in workload, improving continuity of operations."},
{cat:"management", q:"A fire extinguisher rated 'ABC' can be used on:", choices:["Only electrical fires","Common combustibles, flammable liquids, and electrical fires","Only paper","No fires"], answer:1, why:"An ABC extinguisher handles Class A (ordinary combustibles), B (flammable liquids), and C (electrical) fires."},
{cat:"management", q:"Quality improvement (QI) in a medical office focuses on:", choices:["Blaming staff","Continuously improving processes and patient outcomes","Reducing documentation","Avoiding change"], answer:1, why:"QI uses data and teamwork to improve processes, safety, and patient outcomes over time."},

/* ========== Professionalism (30) ========== */
{cat:"professionalism", q:"Which task is OUTSIDE a medical assistant's scope of practice?", choices:["Taking vital signs","Diagnosing a patient's condition","Preparing the exam room","Documenting the chief complaint"], answer:1, why:"Diagnosing (and prescribing) is the provider's responsibility; MAs support care but do not diagnose or prescribe."},
{cat:"professionalism", q:"Which is generally WITHIN a medical assistant's scope of practice?", choices:["Prescribing antibiotics","Performing venipuncture under provider direction","Interpreting x-rays","Independently diagnosing"], answer:1, why:"With training and provider direction, MAs perform tasks like venipuncture and vital signs; they do not prescribe, diagnose, or interpret imaging."},
{cat:"professionalism", q:"'Active listening' with a patient means:", choices:["Interrupting to save time","Giving full attention and paraphrasing to confirm understanding","Looking only at the computer","Finishing their sentences"], answer:1, why:"Active listening, full attention, eye contact, and reflecting back, ensures accurate understanding and builds trust."},
{cat:"professionalism", q:"Empathy in patient care is best described as:", choices:["Feeling sorry for the patient","Understanding and sharing the patient's feelings","Ignoring emotions","Giving medical advice"], answer:1, why:"Empathy is understanding and relating to the patient's feelings and perspective, which improves rapport and care."},
{cat:"professionalism", q:"The most professional response to an angry patient is to:", choices:["Argue back","Stay calm, listen, and acknowledge their concerns","Walk away","Raise your voice"], answer:1, why:"Remaining calm, listening, and validating concerns de-escalates conflict and maintains professionalism."},
{cat:"professionalism", q:"Maintaining patient confidentiality outside of work means:", choices:["Discussing interesting cases with family","Never sharing patient information socially or online","Posting about your day on social media","Telling close friends only"], answer:1, why:"Confidentiality and HIPAA extend beyond the workplace, never disclose patient information socially or on social media."},
{cat:"professionalism", q:"Nonverbal communication includes:", choices:["Only spoken words","Body language, facial expressions, and tone","Written prescriptions","Lab values"], answer:1, why:"Nonverbal cues such as posture, expression, eye contact, and tone strongly influence communication."},
{cat:"professionalism", q:"A professional appearance for a medical assistant includes:", choices:["Heavy perfume and long nails","Clean uniform, good hygiene, and minimal jewelry","Casual beachwear","Strong cologne"], answer:1, why:"A neat uniform, good hygiene, short clean nails, and minimal jewelry support safety and a professional image."},
{cat:"professionalism", q:"When a task is beyond your training or scope, you should:", choices:["Attempt it anyway","Ask for help or refer to the appropriate person","Hide the request","Tell the patient it is impossible"], answer:1, why:"Recognizing limits and seeking help or referral protects patients and is part of professional accountability."},
{cat:"professionalism", q:"Cultural competence means:", choices:["Treating everyone identically without thought","Respecting and responding to patients' diverse beliefs and needs","Ignoring cultural differences","Imposing your own beliefs"], answer:1, why:"Cultural competence is awareness and respect for diverse values and practices, adapting care accordingly."},
{cat:"professionalism", q:"When communicating with a hearing-impaired patient, the MA should:", choices:["Shout","Face the patient, speak clearly, and use written aids or an interpreter as needed","Turn away while talking","Speak only to the family"], answer:1, why:"Facing the patient, clear speech, written materials, or a sign-language interpreter improve communication for the hearing impaired."},
{cat:"professionalism", q:"When working with a visually impaired patient, the MA should:", choices:["Move things without telling them","Announce your presence and describe actions and surroundings","Stay silent","Rearrange the room"], answer:1, why:"Identifying yourself, explaining actions, and orienting the patient supports safety and dignity."},
{cat:"professionalism", q:"Therapeutic communication is communication that:", choices:["Focuses on the MA's needs","Supports the patient and encourages them to express concerns","Uses heavy jargon","Avoids the patient"], answer:1, why:"Therapeutic communication centers on the patient, using open-ended questions, listening, and empathy."},
{cat:"professionalism", q:"An example of a barrier to communication is:", choices:["Eye contact","Using medical jargon the patient does not understand","Speaking clearly","Listening"], answer:1, why:"Jargon, noise, language differences, and distractions are barriers that hinder understanding."},
{cat:"professionalism", q:"Maintaining patient trust requires the MA to be:", choices:["Inconsistent","Honest, reliable, and respectful","Judgmental","Dismissive"], answer:1, why:"Honesty, reliability, and respect build the trust essential to the patient relationship."},
{cat:"professionalism", q:"Punctuality and reliability at work reflect:", choices:["Poor habits","Professional responsibility and respect for the team","Unimportant traits","Optional behavior"], answer:1, why:"Being on time and dependable supports patient care and shows respect for coworkers and patients."},
{cat:"professionalism", q:"To maintain certification, a medical assistant usually must:", choices:["Do nothing","Complete continuing education and renew on schedule","Retake high school","Change careers"], answer:1, why:"Most credentials require continuing education units and periodic renewal to stay current and certified."},
{cat:"professionalism", q:"Professional boundaries mean the MA should:", choices:["Become personal friends with all patients","Keep the relationship professional and focused on care","Lend patients money","Share personal problems with patients"], answer:1, why:"Maintaining appropriate boundaries keeps the focus on the patient's care and avoids conflicts of interest."},
{cat:"professionalism", q:"Patient advocacy means the MA:", choices:["Decides for the patient","Supports the patient's interests and helps them access care","Ignores patient wishes","Speaks only for the provider"], answer:1, why:"Advocacy involves supporting patients' needs and rights and helping them navigate the healthcare system."},
{cat:"professionalism", q:"When you make a mistake at work, the professional action is to:", choices:["Hide it","Report it promptly and help correct it","Blame a coworker","Ignore it"], answer:1, why:"Accountability means promptly reporting errors so they can be corrected and prevented, protecting patient safety."},
{cat:"professionalism", q:"When a patient is anxious before a procedure, the MA should:", choices:["Rush them","Explain calmly, answer questions, and offer reassurance","Tell them to relax and leave","Ignore the anxiety"], answer:1, why:"Calm explanation, listening, and reassurance reduce anxiety and improve cooperation."},
{cat:"professionalism", q:"Open-ended questions are useful because they:", choices:["Get a yes/no answer","Encourage the patient to share more information","Stop conversation","Confuse the patient"], answer:1, why:"Open-ended questions invite patients to describe concerns in detail, yielding richer information."},
{cat:"professionalism", q:"Teamwork in a medical office is best supported by:", choices:["Working in isolation","Clear communication and mutual respect","Withholding information","Competing with coworkers"], answer:1, why:"Effective teams communicate clearly, share information, and respect each member's role for safe, efficient care."},
{cat:"professionalism", q:"When you disagree with a coworker, the professional approach is to:", choices:["Argue in front of patients","Discuss it calmly and privately","Ignore them permanently","Complain to patients"], answer:1, why:"Addressing conflict calmly and privately maintains professionalism and protects the patient experience."},
{cat:"professionalism", q:"Showing respect for patient diversity includes:", choices:["Stereotyping by group","Treating each patient as an individual without bias","Refusing certain patients","Imposing personal values"], answer:1, why:"Respecting diversity means providing unbiased, individualized care to every patient."},
{cat:"professionalism", q:"Confidential conversations about patients should occur:", choices:["In the waiting room","In private areas where they cannot be overheard","On social media","In the elevator"], answer:1, why:"Discussing patient information only in private, need-to-know settings protects confidentiality."},
{cat:"professionalism", q:"A medical assistant's dependability includes:", choices:["Frequent unexplained absences","Following through on tasks and being trustworthy","Leaving work unfinished","Avoiding responsibility"], answer:1, why:"Dependability, completing tasks and being trustworthy, is essential to safe team-based care."},
{cat:"professionalism", q:"When speaking with an older adult patient, the MA should:", choices:["Use baby talk","Speak respectfully and clearly, allowing time to respond","Assume they cannot understand","Talk only to caregivers"], answer:1, why:"Respectful, clear communication that allows time and avoids condescension honors the patient's dignity."},
{cat:"professionalism", q:"Empathy differs from sympathy in that empathy:", choices:["Means feeling pity","Means understanding the patient's experience from their perspective","Ignores feelings","Is unprofessional"], answer:1, why:"Empathy is understanding and sharing another's feelings/perspective, while sympathy is feeling pity for them."},
{cat:"professionalism", q:"Stress management for a medical assistant is important because:", choices:["It is unnecessary","It helps prevent burnout and maintains quality care","It wastes time","Patients prefer stressed staff"], answer:1, why:"Managing stress sustains well-being, focus, and the quality of patient care, helping prevent burnout."},

/* ========== Medical Law & Ethics (12) ========== */
{cat:"lawethics", q:"HIPAA primarily protects:", choices:["Hospital profits","The privacy and security of patients' health information","Physician licenses","Insurance companies"], answer:1, why:"HIPAA safeguards the privacy and security of protected health information (PHI)."},
{cat:"lawethics", q:"Informed consent requires that the patient understands:", choices:["Only the cost","The risks, benefits, and alternatives before a procedure","Nothing, staff decide","The provider's schedule"], answer:1, why:"Informed consent means the patient is told the risks, benefits, and alternatives and voluntarily agrees before a procedure."},
{cat:"lawethics", q:"Releasing a patient's PHI to a third party generally requires:", choices:["A verbal okay from staff","The patient's written authorization","Nothing in any situation","The provider's preference"], answer:1, why:"Disclosing PHI outside treatment, payment, or operations generally requires the patient's signed authorization under HIPAA."},
{cat:"lawethics", q:"Treating all patients fairly regardless of race, religion, or background reflects:", choices:["Negligence","Nondiscrimination and respect for diversity","Defamation","Malpractice"], answer:1, why:"Providing equitable care and respecting diversity is both an ethical duty and a legal requirement in healthcare."},
{cat:"lawethics", q:"Negligence in healthcare is best described as:", choices:["Intentional harm","Failure to provide the standard of care, causing harm","A billing error","A scheduling mistake"], answer:1, why:"Negligence is failing to act as a reasonably prudent professional would, resulting in patient harm."},
{cat:"lawethics", q:"Battery in a medical context refers to:", choices:["Charging too much","Touching or treating a patient without consent","A dead phone","A lab error"], answer:1, why:"Battery is unauthorized physical contact or treatment without the patient's consent."},
{cat:"lawethics", q:"The minimum necessary standard under HIPAA means:", choices:["Share everything","Use or disclose only the PHI needed for the task","Never document","Tell everyone"], answer:1, why:"Staff should access and share only the minimum PHI necessary to accomplish the intended purpose."},
{cat:"lawethics", q:"A patient has the right to:", choices:["Demand illegal drugs","Refuse treatment","Access another patient's chart","Avoid all bills"], answer:1, why:"Competent patients have the right to refuse treatment after being informed of the consequences."},
{cat:"lawethics", q:"An advance directive is a document that:", choices:["Schedules appointments","States a patient's wishes for care if they cannot decide","Bills insurance","Lists medications only"], answer:1, why:"An advance directive (e.g., living will) records a patient's healthcare wishes for situations when they cannot communicate them."},
{cat:"lawethics", q:"Mandatory reporting laws may require healthcare workers to report:", choices:["A patient's job","Suspected abuse or certain communicable diseases","Insurance choices","Appointment times"], answer:1, why:"Laws require reporting of suspected child/elder abuse and certain communicable diseases to protect public welfare."},
{cat:"lawethics", q:"Defamation that is written is called:", choices:["Slander","Libel","Battery","Assault"], answer:1, why:"Libel is written defamation; slander is spoken defamation, both can harm reputation."},
{cat:"lawethics", q:"Discussing a patient's information in a crowded elevator is:", choices:["Acceptable","A potential HIPAA/privacy violation","Required","Good teamwork"], answer:1, why:"Talking about PHI where it can be overheard risks an unauthorized disclosure and violates privacy rules."},
];
